#include <cassert>
#include <cstddef>
#include <cstdint>
#include <format>
#include <functional>
#include <iostream>
#include <numeric>
#include <span>
#include <vector>

struct IndexRange {
  std::ptrdiff_t first = 0;
  std::ptrdiff_t last = 0;  // one past the end
};

class RangeSums {
 public:
  explicit RangeSums(std::span<const int> nums) : prefix_(nums.size() + 1) {
    // prefix_[i] is the sum of the first i elements; prefix_[0] stays 0, the empty prefix.
    std::inclusive_scan(nums.begin(), nums.end(), prefix_.begin() + 1, std::plus<>{}, std::int64_t{0});
  }

  // Precondition: 0 <= r.first <= r.last <= the number of elements.
  [[nodiscard]] std::int64_t sum(IndexRange r) const {
    assert(0 <= r.first && r.first <= r.last && r.last < std::ssize(prefix_));
    return prefix_[r.last] - prefix_[r.first];
  }

 private:
  std::vector<std::int64_t> prefix_;
};

int main() {
  const std::vector<int> nums{3, -1, 4, 1, 5};
  const RangeSums sums(nums);
  std::cout << std::format("{} {} {}\n", sums.sum({.first = 1, .last = 4}), sums.sum({.first = 0, .last = 5}),
                           sums.sum({.first = 2, .last = 2}));
}

