[[nodiscard]] std::optional<std::ptrdiff_t> longest_with_sum(std::span<const int> nums, std::int64_t k) {
  std::unordered_map<std::int64_t, std::ptrdiff_t> first_index{{0, 0}};  // the empty prefix, at index 0
  std::optional<std::ptrdiff_t> best;
  std::int64_t prefix = 0;
  for (std::ptrdiff_t i = 0; i < std::ssize(nums); ++i) {
    prefix += nums[i];
    const std::ptrdiff_t end = i + 1;  // prefix is now P(end), the sum of the first end elements
    if (const auto it = first_index.find(prefix - k); it != first_index.end()) {
      const std::ptrdiff_t length = end - it->second;
      if (!best || length > *best) best = length;
    }
    first_index.try_emplace(prefix, end);  // keeps the first index; a later one would give a shorter run
  }
  return best;
}

[[nodiscard]] std::string show(const std::optional<std::ptrdiff_t>& length) {
  return length ? std::to_string(*length) : "no value";
}

int main() {
  const std::vector<int> turns{+1, -1, -1, +1, +1, +1};
  for (const std::int64_t k : {0, 2, 3}) std::cout << std::format("k = {}: {}\n", k, show(longest_with_sum(turns, k)));
  std::cout << std::format("empty log: {}\n", show(longest_with_sum(std::vector<int>{}, 0)));
}

#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <random>
#include <span>
#include <unordered_map>
#include <vector>

[[nodiscard]] std::int64_t count_subarrays(std::span<const int> nums, std::int64_t k) {
  std::unordered_map<std::int64_t, std::int64_t> times_seen{{0, 1}};  // prefix value -> how often; the empty prefix once
  std::int64_t count = 0;
  std::int64_t prefix = 0;
  for (const int x : nums) {
    prefix += x;
    if (const auto it = times_seen.find(prefix - k); it != times_seen.end()) count += it->second;
    ++times_seen[prefix];
  }
  return count;
}

// Tries every subarray: O(n²), for testing only.
[[nodiscard]] std::int64_t count_subarrays_slow(std::span<const int> nums, std::int64_t k) {
  std::int64_t count = 0;
  for (std::ptrdiff_t first = 0; first < std::ssize(nums); ++first) {
    std::int64_t sum = 0;
    for (std::ptrdiff_t last = first; last < std::ssize(nums); ++last) {
      sum += nums[last];
      if (sum == k) ++count;
    }
  }
  return count;
}

// Returns how many of `cases` random inputs the two versions agree on.
[[nodiscard]] std::int64_t agreeing_cases(std::uint32_t seed, std::int64_t cases) {
  std::mt19937 generator{seed};
  std::uniform_int_distribution<int> length{0, 12};
  std::uniform_int_distribution<int> value{-3, 3};
  std::int64_t agree = 0;
  for (std::int64_t c = 0; c < cases; ++c) {
    std::vector<int> nums(static_cast<std::size_t>(length(generator)));
    for (int& x : nums) x = value(generator);
    const std::int64_t k = value(generator);
    if (count_subarrays(nums, k) == count_subarrays_slow(nums, k)) ++agree;
  }
  return agree;
}

int main() {
  const std::vector<int> a{1, 1, 1};
  const std::vector<int> b{1, 2, 3};
  const std::vector<int> c{1, -1, 0};
  std::cout << std::format("{} {} {}\n", count_subarrays(a, 2), count_subarrays(b, 3), count_subarrays(c, 0));
  std::cout << std::format("{} of 1000 random cases agree\n", agreeing_cases(2026, 1000));
}

#include <cstddef>
#include <cstdint>
#include <functional>
