#include <span>
#include <string_view>
#include <vector>

[[nodiscard]] std::vector<std::int64_t> products_except_self(std::span<const int> nums) {
  std::vector<std::int64_t> out(nums.size());
  // out[i] = product of nums[0..i-1]; out[0] is the empty product, 1. Multiplies in 64 bits.
  std::exclusive_scan(nums.begin(), nums.end(), out.begin(), std::int64_t{1}, std::multiplies<>{});
  std::int64_t suffix = 1;  // product of nums[i+1..n-1]
  for (std::ptrdiff_t i = std::ssize(nums) - 1; i >= 0; --i) {
    out[i] *= suffix;
    suffix *= nums[i];
  }
  return out;
}

int main() {
  const std::vector<std::vector<int>> inputs{{1, 2, 3, 4}, {0, 2, 3}, {0, 0, 5}, {-1, 2, -3}, {5}, {}};
  for (const std::vector<int>& nums : inputs) {
    const std::vector<std::int64_t> products = products_except_self(nums);
    std::string_view separator;
    for (const std::int64_t p : products) {
      std::cout << separator << p;
      separator = " ";
    }
    std::cout << (products.empty() ? "(empty)\n" : "\n");
  }
}

