#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <unordered_map>
#include <vector>

[[nodiscard]] std::int64_t count_divisible_raw(std::span<const int> nums, std::int64_t m) {
  std::unordered_map<std::int64_t, std::int64_t> times_seen{{0, 1}};
  std::int64_t count = 0;
  std::int64_t prefix = 0;
  for (const int x : nums) {
    prefix += x;
    const std::int64_t remainder = prefix % m;  // wrong: negative for a negative prefix
    if (const auto it = times_seen.find(remainder); it != times_seen.end()) count += it->second;
    ++times_seen[remainder];
  }
  return count;
}

[[nodiscard]] std::int64_t count_divisible(std::span<const int> nums, std::int64_t m) {
  std::unordered_map<std::int64_t, std::int64_t> times_seen{{0, 1}};
  std::int64_t count = 0;
  std::int64_t prefix = 0;
  for (const int x : nums) {
    prefix += x;
    const std::int64_t remainder = (prefix % m + m) % m;  // in [0, m) for m > 0
    if (const auto it = times_seen.find(remainder); it != times_seen.end()) count += it->second;
    ++times_seen[remainder];
  }
  return count;
}

int main() {
  const std::vector<int> nums{2, -3, 1, 4};
  std::cout << std::format("raw remainder: {}, normalised: {}\n", count_divisible_raw(nums, 3), count_divisible(nums, 3));
}
